/**
 * Water consumption card — v2 (mobile). Pixel rebuild, not a screenshot trace.
 *
 * Design source: Figma file YEmjkKS4xaA827Zm8w3oXx
 *   198424:63770  Property 1=Daily  — populated chart
 *   198424:63772  Property 1=Empty  — empty state
 * Both variants were fetched individually, never through the parent frame,
 * which merges variants and hands back the wrong assets.
 *
 * ── Why every Figma class here is a String.raw`` template ──────────────────
 * Figma emits its tokens as `var(--colors\/slate\/800,#1d293d)`: the backslash
 * is what tells Tailwind the slash is part of the name and not an opacity
 * modifier, and it must survive into the class attribute. In a JSX attribute
 * that is free, but the moment a class goes through cn() it becomes a JS
 * string, and `'\/'` collapses to `/` while `'\\/'` becomes `\\/` in the
 * source the Tailwind scanner reads. Verified against this project's own
 * tailwindcss@4.2.2 + @tailwindcss/oxide: the JS-string spellings generate a
 * selector the runtime class never matches, and String.raw`` is the only form
 * where the scanned candidate and the emitted class are the same bytes. So
 * every Figma class below is String.raw. Do not "tidy" them into plain quotes.
 *
 * ── Why some Figma fallbacks were corrected ───────────────────────────────
 * Figma emits every token as `var(--name, <fallback>)`. On this file a batch
 * of those fallbacks are STALE — get_variable_defs on both nodes resolves
 * them to different numbers, and the 932px render agrees with the resolved
 * value, not the fallback. Measured off the native-resolution screenshot:
 * the "June 2026" button is 36px tall (y=13..48) and the title's first dark
 * pixel is x=26, i.e. 1px border + 24px padding. So the token NAMES are kept
 * verbatim and only the literal fallback is set to the resolved value:
 *
 *   component/card/padding                 16px → 24px
 *   component/card/header/gap               4px →  8px
 *   component/pro/…/inline-hint/rail/width  4px → 12px   (header pt)
 *   component/button/size-default/px       10px → 12px
 *   component/button/size-default/radius   10px → 26px   (a pill)
 *   component/button/size-default/height     —  → 36px
 *   component/toggle/size-default/padding  10px → 12px
 *   component/toggle/radius                10px → 26px
 *   component/toggle/size-default/height     —  → 36px
 *   pro/space/2                             6px →  8px
 *   pro/space/4                            12px → 16px
 *
 * Three more tokens are emitted under names this project already defines with
 * a DIFFERENT value, so `var()` would resolve to the project's number and miss
 * the design. Those are written as the design literal instead:
 *   --muted-foreground     design #737373 / project #62748e (axis + body copy)
 *   --border               design #e5e5e5 / project #e2e8f0 (gridlines)
 *   --secondary-foreground design #171717 / project #0b81f8 (stepper label)
 * Everything else — colors/slate/*, colors/blue/50, wint-blue-accent,
 * spacing/*, text/*, rounded-2xl — is undefined here, so the verbatim
 * `var(--token, literal)` renders the exact design value.
 *
 * Font: font/family/sans and font/family/heading both resolve to Figtree, but
 * Figma's fallback string says 'Geist:SemiBold' — an unmatchable family that
 * would drop the browser to its serif default. Body text therefore carries no
 * font-family class and inherits Figtree from `html, body, #root`. Only the
 * chart axis labels are Geist, via the project's --font-mono-label.
 *
 * Shadow: the card's "Liquid" effect is two drop-shadow layers; Figma's codegen
 * emitted only layer-2, which resolves to fully transparent with 0 blur — i.e.
 * no shadow at all. Layer-1 (0 25px 50px -12px #0000001a) is the visible one
 * and it needs spread, which `drop-shadow()` cannot express, so it is rendered
 * as a box-shadow.
 */

import { useState } from 'react'
import { Bar, BarChart, CartesianGrid, XAxis, YAxis } from 'recharts'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart'
import { Button } from '@/components/ui/button'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { cn } from '@/lib/utils'

/* ── Inlined Figma assets ──────────────────────────────────────────────────
   Figma's asset URLs expire in ~7 days, so nothing may reference them at
   runtime. Each one below is the downloaded artwork, viewBox verbatim.

   NOTE on the chevrons: fetching the card node returned ONE url for both icon
   slots, and the SVG behind it was `Lucide Icons / smile` — the component's
   untouched Icon Placeholder default, not what the frame renders. Fetching the
   two leaf nodes individually returned the real glyphs (Tabler chevron-left /
   chevron-right, 16x16, stroke #62748E, width 1.33). Geometry checked: a
   3-point polyline inside a 16x16 box is a chevron; the smile asset was a
   14.67-diameter circle with two eyes, which is not. Stroke is left at the
   shipped #62748E — the design tints both the same, so nothing to recolour. */

// Tabler Icons / chevron-left — Figma asset 07a4d214-d3e5-4a7e-8807-548b1509dc25
function ChevronLeft16({ className }) {
  return (
    <svg
      className={className}
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M10 4L6 8L10 12"
        stroke="#62748E"
        strokeWidth="1.33"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

// Tabler Icons / chevron-right — Figma asset 50984ff1-8718-4840-b2ea-cb789fc59a21
function ChevronRight16({ className }) {
  return (
    <svg
      className={className}
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      <path
        d="M6 4L10 8L6 12"
        stroke="#62748E"
        strokeWidth="1.33"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

/* Empty-state illustration — Figma node 198424:63958. It is a raster (PNG),
   not an SVG, so it is inlined as a data URI rather than redrawn or swapped
   for a lookalike. The export is 1448x1086; it is delivered here at 432x324,
   3x the 144x108 box the design draws it in, because a 1448px source is 342KB
   for a 144px slot. Same artwork, same 4:3 aspect, same alpha. */
const EMPTY_ILLUSTRATION = 'data:image/png;base64,'

/* ── Mock data ─────────────────────────────────────────────────────────────
   MOCK — replace with a real series.
   Traced off the Daily comp's own bars: each bar's pixel height over the 185px
   plot box, scaled by the 40K top gridline (litres = px / 185 * 40000, rounded
   to 10 L). So the silhouette is the design's, not an invention. */
const MOCK_DAILY_SERIES = [
  { day: 1, litres: 36760 }, { day: 2, litres: 19680 }, { day: 3, litres: 36760 },
  { day: 4, litres: 28320 }, { day: 5, litres: 21410 }, { day: 6, litres: 36760 },
  { day: 7, litres: 30270 }, { day: 8, litres: 17950 }, { day: 9, litres: 28320 },
  { day: 10, litres: 40000 }, { day: 11, litres: 30270 }, { day: 12, litres: 40000 },
  { day: 13, litres: 36760 }, { day: 14, litres: 19680 }, { day: 15, litres: 36760 },
  { day: 16, litres: 28320 }, { day: 17, litres: 21410 }, { day: 18, litres: 36760 },
  { day: 19, litres: 30270 }, { day: 20, litres: 17950 }, { day: 21, litres: 28320 },
  { day: 22, litres: 40000 }, { day: 23, litres: 30270 }, { day: 24, litres: 28320 },
  { day: 25, litres: 30270 }, { day: 26, litres: 17950 }, { day: 27, litres: 28320 },
  { day: 28, litres: 21410 }, { day: 29, litres: 30270 }, { day: 30, litres: 40000 },
]

// MOCK — the month MOCK_DAILY_SERIES covers. The comp's stepper reads "June 2026".
const MOCK_MONTH = { year: 2026, monthIndex: 5 }

// Y / M / D / H in the comp. The letter is the label; the word is the a11y name.
const PERIODS = [
  { id: 'Y', name: 'Year' },
  { id: 'M', name: 'Month' },
  { id: 'D', name: 'Day' },
  { id: 'H', name: 'Hour' },
]

/* The comp prints 1.8K Total / 12.4K Daily Avg / 28.7K Peak Day, and those
   three cannot all be true of one series: the total sits below the peak, and
   the average is seven times the total. A static frame can carry that; this
   card cannot, because every bar is hoverable and one tap prints the real
   litre value. So the headline row is derived from the series actually
   plotted. Pass `stats` to substitute real aggregates. */
function fmtL(n) {
  if (n >= 1e6) return `${(n / 1e6).toFixed(1).replace(/\.0$/, '')}M`
  if (n >= 1e3) return `${(n / 1e3).toFixed(1).replace(/\.0$/, '')}K`
  return String(Math.round(n))
}

function deriveStats(series) {
  if (!series.length) return []
  const total = series.reduce((sum, d) => sum + d.litres, 0)
  return [
    /* The comp fixes these columns at 62 / 100 / 100 with the copy inside set
       to whitespace-nowrap, i.e. a value wider than its box overflows it. At
       932px that never bites; at 375px a derived "889.5K" would sit on its
       neighbour. min-w- keeps the comp's column rhythm and lets the rare wide
       value push instead of collide. */
    { value: fmtL(total), label: 'Total L', width: 'min-w-[62px]' },
    { value: fmtL(total / series.length), label: 'Daily Avg L', width: 'min-w-[100px]' },
    {
      value: fmtL(Math.max(...series.map((d) => d.litres))),
      label: 'Peak Day L',
      width: 'min-w-[100px]',
    },
  ]
}

/* The comp's y-axis is 0K/10K/20K/30K/40K with the tallest bar landing exactly
   on 40K. Rather than hard-code that, pick the smallest 1/2/2.5/5 x 10^n step
   whose four divisions cover the max — which reproduces the comp for the mock
   and still gives round labels for any other series. */
function niceScale(max, divisions = 4) {
  if (!(max > 0)) return { domainMax: divisions, ticks: [] }
  const magnitude = Math.pow(10, Math.floor(Math.log10(max / divisions)))
  const step =
    [1, 2, 2.5, 5, 10].map((m) => m * magnitude).find((s) => s * divisions >= max) ??
    10 * magnitude
  return {
    domainMax: step * divisions,
    ticks: Array.from({ length: divisions + 1 }, (_, i) => i * step),
  }
}

const fmtAxis = (v) => (v >= 1000 || v === 0 ? `${Number((v / 1000).toFixed(1))}K` : String(v))

// ChartStyle turns this into --color-litres on the container, which is why the
// Bar fill below is a var() and not the literal rgba.
const CHART_CONFIG = {
  litres: { label: 'Litres', color: 'rgba(11,129,248,0.6)' },
}

function formatMonth(offset) {
  return new Date(MOCK_MONTH.year, MOCK_MONTH.monthIndex + offset, 1).toLocaleDateString('en-US', {
    month: 'long',
    year: 'numeric',
  })
}

export default function WaterConsumptionCardV2({
  data = MOCK_DAILY_SERIES,
  stats,
  className,
  /* Optional: let a host own the scope controls. When either callback is
     supplied the host is responsible for swapping `data` to match, so the card
     plots `data` for whatever scope is showing. */
  period: periodProp,
  onPeriodChange,
  monthLabel: monthLabelProp,
  onMonthChange,
}) {
  const [periodState, setPeriodState] = useState('D')
  const [monthOffset, setMonthOffset] = useState(0)

  const hostOwnsScope = Boolean(onPeriodChange || onMonthChange)
  const period = periodProp ?? periodState
  const monthLabel = monthLabelProp ?? formatMonth(monthOffset)

  /* The card is presentational — it plots what it is handed. Uncontrolled (the
     mockup default) the only series that exists is June 2026 daily, so steering
     the stepper or the Y / M / H segments lands on the empty state instead of
     replaying the same 30 bars under a different heading. */
  const scopeSteered = hostOwnsScope || period !== 'D' || monthOffset !== 0
  const series = hostOwnsScope || !scopeSteered ? data : []
  const isEmpty = series.length === 0

  /* Figma's Empty variant drops the header controls entirely — that is the
     "this system has never reported" state, reached here with data={[]}. When
     the card is empty only because the viewer steered the scope, the controls
     stay put so they can steer back; hiding them would be a dead end. */
  const showControls = !isEmpty || scopeSteered

  const headline = stats ?? deriveStats(series)
  const { domainMax, ticks } = niceScale(Math.max(0, ...series.map((d) => d.litres)))
  // ~8 x-axis labels at any window; 30 day numbers do not fit across 375px.
  const tickInterval = Math.max(0, Math.ceil(series.length / 8) - 1)

  const selectPeriod = (next) => {
    if (!next) return // radix clears the value when the active item is re-tapped
    setPeriodState(next)
    onPeriodChange?.(next)
  }

  const stepMonth = (delta) => {
    setMonthOffset((offset) => offset + delta)
    onMonthChange?.(delta)
  }

  return (
    <Card
      className={cn(
        String.raw`gap-0 border-white bg-[#fafbfc] py-0 rounded-[var(--rounded-2xl,18px)]`,
        'shadow-[0px_25px_50px_-12px_rgba(0,0,0,0.1)]',
        className,
      )}
      data-node-id={isEmpty && !scopeSteered ? '198424:63772' : '198424:63770'}
    >
      <CardHeader
        className={cn(
          String.raw`items-center gap-[var(--component\/card\/header\/gap,8px)]`,
          String.raw`px-[var(--component\/card\/padding,24px)]`,
          String.raw`pt-[var(--component\/pro\/application\/inline-hint\/rail\/width,12px)]`,
          String.raw`pb-[var(--spacing\/3,12px)]`,
        )}
      >
        <CardTitle
          className={cn(
            String.raw`w-full font-semibold tracking-[-0.45px]`,
            String.raw`text-[length:var(--text\/lg\/size,18px)] leading-[var(--text\/lg\/lh-none,18px)]`,
            String.raw`text-[color:var(--colors\/slate\/800,#1d293d)]`,
          )}
        >
          Water consumption
        </CardTitle>
      </CardHeader>

      {showControls && (
        /* Desktop puts the stepper and the segmented control on the title row.
           At 375px the title (~150px) plus both clusters (~273px) overflows, so
           the cluster drops to its own row — the 12px gap between them is the
           comp's. Nothing else about either control changes. */
        <div
          className={cn(
            'flex flex-wrap items-center justify-between gap-[12px]',
            String.raw`px-[var(--component\/card\/padding,24px)] pb-[var(--spacing\/3,12px)]`,
          )}
        >
          {/* Figma maps this to data-slot="button", so it is the Button
              primitive — but the comp's pill carries a chevron at EACH end, and
              one <button> cannot hold two actions. `asChild` keeps the
              primitive's styling and data-slot on the pill while letting the two
              chevrons be real buttons inside it. The month label between them is
              deliberately inert: it reports the scope, it does not change it. */}
          <Button
            asChild
            variant="secondary"
            className={cn(
              String.raw`h-[var(--component\/button\/size-default\/height,36px)]`,
              String.raw`gap-[var(--component\/button\/gap,6px)]`,
              String.raw`rounded-[var(--component\/button\/size-default\/radius,26px)]`,
              // both spellings: the primitive's own has-[>svg]:px-3 carries a
              // modifier a plain px-* cannot out-specify
              String.raw`px-[var(--component\/button\/size-default\/px,12px)]`,
              String.raw`has-[>svg]:px-[var(--component\/button\/size-default\/px,12px)]`,
              // the pill is no longer the tap target — the two chevrons are, and
              // they light up on their own — so its hover is pinned to the rest
              // colour. Left alone it would inherit hover:bg-secondary/80, and
              // this project's --secondary (#f2f6ff) is blue, not slate.
              String.raw`bg-[var(--colors\/slate\/100,#f1f5f9)] hover:bg-[var(--colors\/slate\/100,#f1f5f9)]`,
              String.raw`text-[length:var(--text\/sm-tight\/size,14px)] leading-[var(--text\/sm-tight\/lh,20px)]`,
              // design --secondary-foreground is #171717; this project's is #0b81f8
              'text-[#171717]',
            )}
          >
            <div role="group" aria-label="Period">
              <button
                type="button"
                aria-label="Previous month"
                onClick={() => stepMonth(-1)}
                // -m-1/p-1 buys a 24px tap target without moving the 16px glyph
                className="-m-1 rounded-full p-1 outline-none hover:bg-[rgba(0,0,0,0.06)] focus-visible:ring-[3px] focus-visible:ring-ring/50"
              >
                <ChevronLeft16 className="size-4" />
              </button>
              <span>{monthLabel}</span>
              <button
                type="button"
                aria-label="Next month"
                onClick={() => stepMonth(1)}
                className="-m-1 rounded-full p-1 outline-none hover:bg-[rgba(0,0,0,0.06)] focus-visible:ring-[3px] focus-visible:ring-ring/50"
              >
                <ChevronRight16 className="size-4" />
              </button>
            </div>
          </Button>

          {/* Figma marks each segment data-slot="toggle" inside a shared "slot"
              row: that is ToggleGroup variant=outline spacing=0, whose
              first:rounded-l / last:rounded-r / border-l-0 rules are exactly the
              border pattern the four comp segments draw. */}
          <ToggleGroup
            type="single"
            variant="outline"
            spacing={0}
            value={period}
            onValueChange={selectPeriod}
            aria-label="Consumption granularity"
            className="shrink-0"
          >
            {PERIODS.map((p) => (
              <ToggleGroupItem
                key={p.id}
                value={p.id}
                aria-label={p.name}
                className={cn(
                  String.raw`h-[var(--component\/toggle\/size-default\/height,36px)]`,
                  String.raw`px-[var(--component\/toggle\/size-default\/padding,12px)]`,
                  String.raw`gap-[var(--component\/toggle\/gap,4px)]`,
                  String.raw`data-[spacing=0]:first:rounded-l-[var(--component\/toggle\/radius,26px)]`,
                  String.raw`data-[spacing=0]:last:rounded-r-[var(--component\/toggle\/radius,26px)]`,
                  String.raw`border-[var(--colors\/slate\/200,#e2e8f0)]`,
                  String.raw`text-[length:var(--text\/sm-tight\/size,14px)] leading-[var(--text\/sm-tight\/lh,20px)]`,
                  String.raw`text-[color:var(--colors\/slate\/800,#1d293d)]`,
                  String.raw`data-[state=on]:bg-[var(--colors\/blue\/50,#eff6ff)]`,
                  String.raw`data-[state=on]:text-[color:var(--wint-blue-accent,#0b81f8)]`,
                )}
              >
                {p.id}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </div>
      )}

      {isEmpty ? (
        /* Figma 198424:63772. The illustration sits in a 144x74 window that
           crops a 144x108 image — top -22.97%, height 145.95% — which is what
           trims the empty canvas above the pipe. Both numbers are the comp's. */
        <div
          className={cn(
            'flex min-h-[213px] flex-1 flex-col items-center justify-center',
            String.raw`gap-[var(--pro\/space\/4,16px)]`,
            String.raw`px-[var(--component\/card\/padding,24px)] pb-[var(--spacing\/5,20px)]`,
          )}
        >
          <div className="relative h-[74px] w-[144px] shrink-0">
            <div className="pointer-events-none absolute inset-0 overflow-hidden">
              <img
                alt=""
                className="absolute left-0 top-[-22.97%] h-[145.95%] w-full max-w-none"
                src={EMPTY_ILLUSTRATION}
              />
            </div>
          </div>
          <div
            className={cn(
              'flex w-full flex-col items-center justify-center',
              String.raw`gap-[var(--pro\/space\/2,8px)]`,
            )}
          >
            <div className="flex w-full flex-col items-center justify-center gap-[4px] text-center">
              <p
                className={cn(
                  String.raw`w-full font-semibold tracking-[-0.45px]`,
                  String.raw`text-[length:var(--text\/lg\/size,18px)] leading-[var(--text\/lg\/lh-none,18px)]`,
                  String.raw`text-[color:var(--colors\/slate\/800,#1d293d)]`,
                )}
              >
                Nothing flowed in yet
              </p>
              {/* Copy is the comp's, verbatim — including "rlevant". That typo
                  lives in Figma node 198424:63962; fix it there, not here, or
                  the next re-derive silently reverts it. */}
              <p
                className={cn(
                  'w-full text-[#737373]',
                  String.raw`text-[length:var(--text\/sm\/size,14px)] leading-[var(--text\/sm\/lh,20px)]`,
                )}
              >
                We’ll show your data when it’s rlevant
              </p>
            </div>
          </div>
        </div>
      ) : (
        <>
          <CardContent
            className={cn(
              'flex items-start gap-[10px]',
              String.raw`px-[var(--component\/card\/padding,24px)]`,
            )}
          >
            {headline.map((stat) => (
              <div
                key={stat.label}
                className={cn(
                  String.raw`flex shrink-0 flex-col gap-[var(--pro\/space\/0\,5,2px)]`,
                  stat.width ?? 'min-w-[100px]',
                )}
              >
                <p
                  className={cn(
                    'whitespace-nowrap font-medium tabular-nums',
                    String.raw`text-[length:var(--text\/xl\/size,20px)] leading-[var(--text\/xl\/lh-snug,27.5px)]`,
                    String.raw`tracking-[var(--text\/xl\/heading-tracking,-0.5px)]`,
                    String.raw`text-[color:var(--colors\/slate\/800,#1d293d)]`,
                  )}
                >
                  {stat.value}
                </p>
                <p
                  className={cn(
                    'whitespace-nowrap font-medium',
                    String.raw`text-[length:var(--text\/base\/size,14px)] leading-[var(--text\/base\/lh,18px)]`,
                    String.raw`text-[color:var(--colors\/slate\/400,#90a1b9)]`,
                  )}
                >
                  {stat.label}
                </p>
              </div>
            ))}
          </CardContent>

          <CardContent
            className={cn(
              String.raw`px-[var(--component\/card\/padding,24px)]`,
              String.raw`pt-[var(--pro\/space\/4,16px)] pb-[var(--spacing\/5,20px)]`,
            )}
          >
            {/* aspect-auto cancels ChartContainer's aspect-video: the phone frame
                needs an explicit height, never a fixed pixel width. 213px is the
                comp's 185px plot box plus its 28px day row. Axis type is Geist
                (--font-mono-label); the #737373 fill is the design's
                muted-foreground, which is not this project's. */}
            <ChartContainer
              config={CHART_CONFIG}
              className={cn(
                'aspect-auto h-[213px] w-full',
                '[&_.recharts-cartesian-axis-tick_text]:fill-[#737373]',
              )}
            >
              <BarChart
                accessibilityLayer
                data={series}
                barCategoryGap="42%"
                margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
              >
                {/* #e5e5e5 is the stroke on the comp's own gridline vector. */}
                <CartesianGrid vertical={false} stroke="#e5e5e5" />
                <YAxis
                  dataKey="litres"
                  width={37}
                  domain={[0, domainMax]}
                  ticks={ticks}
                  tickLine={false}
                  axisLine={false}
                  tickFormatter={fmtAxis}
                  tick={{ fontFamily: 'var(--font-mono-label)', fontSize: 12 }}
                />
                <XAxis
                  dataKey="day"
                  height={28}
                  tickLine={false}
                  axisLine={false}
                  tickMargin={8}
                  interval={tickInterval}
                  tick={{ fontFamily: 'var(--font-mono-label)', fontSize: 12 }}
                />
                <ChartTooltip
                  cursor={{ fill: 'var(--color-litres)', fillOpacity: 0.12 }}
                  content={<ChartTooltipContent labelFormatter={(day) => `${monthLabel} ${day}`} />}
                />
                {/* radius 100 is the comp's rounded-t-[100px]; recharts clamps it
                    to min(width, height) / 2, the same half-round cap the 16.6px
                    Figma bars get. Grow-in animation is off: recharts drives it
                    from rAF, which never ticks under happy-dom, so a DOM test of
                    this card would see empty bars. */}
                <Bar
                  dataKey="litres"
                  fill="var(--color-litres)"
                  radius={[100, 100, 0, 0]}
                  isAnimationActive={false}
                />
              </BarChart>
            </ChartContainer>
          </CardContent>
        </>
      )}
    </Card>
  )
}
